files.content:
* {
  box-sizing: border-box;
  margin: 0;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 850px;
  min-height: 100vh;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
}

.cat-title {
  margin-bottom: 30px;
  font-size: 100%;
}

.text-box {
  border: 1px solid #000;
  border-left: none;
  padding: 2.5%;
  background-color: #ffc802;
}

.parent {
  display: flex;
  margin: 0 50px;
  font-size: 30px;
}

.cat-image {
  height: 100vh;
  border: 1px solid #000;
}

.cat-text {
  font-size: 60%;
  line-height: 150%;
}
